"""Copy the tested command worker into the TypeScript package."""

import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
source = (root / "packages/inspect-lizard/src/inspect_lizard/_worker.py").read_text()
target = root / "packages/mastra/src/worker.ts"
target.write_text(
    "// Generated by scripts/sync-worker.py.\nexport const WORKER_SOURCE: string = "
    + json.dumps(source)
    + ";\n"
)
